#include <stdio.h>

int main(void) {
    int a[2][3][4];
    /* 行优先：a[i][j][k] 的偏移 = (i*3*4 + j*4 + k) * sizeof(int) */
    for (int i = 0; i < 2; i++)
        for (int j = 0; j < 3; j++)
            for (int k = 0; k < 4; k++)
                printf("a[%d][%d][%d] offset=(%d*12+%d*4+%d)*4\n",
                       i, j, k, i, j, k);
    return 0;
}
